import copy
import unittest

from unique import stable_unique


class StableUniqueTest(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(stable_unique([]), [])

    def test_hashable(self):
        self.assertEqual(stable_unique([3, 1, 3, 2, 1]), [3, 1, 2])

    def test_strings(self):
        self.assertEqual(stable_unique(list("banana")), ["b", "a", "n"])

    def test_no_duplicates(self):
        self.assertEqual(stable_unique([1, 2, 3]), [1, 2, 3])

    def test_unhashable_lists(self):
        self.assertEqual(stable_unique([[1], [2], [1], [2, 3], [2]]), [[1], [2], [2, 3]])

    def test_unhashable_dicts(self):
        self.assertEqual(stable_unique([{"a": 1}, {"a": 1}, {"b": 2}]), [{"a": 1}, {"b": 2}])

    def test_mixed(self):
        self.assertEqual(
            stable_unique([1, [1], 1, "x", [1], {"k": 1}, "x", {"k": 1}]),
            [1, [1], "x", {"k": 1}],
        )

    def test_equality_across_types(self):
        # 1 == 1.0 == True in Python; first occurrence wins.
        self.assertEqual(stable_unique([1, 1.0, True, 2]), [1, 2])

    def test_first_occurrence_identity_kept(self):
        a = [1]
        b = [1]
        result = stable_unique([a, b])
        self.assertIs(result[0], a)
        self.assertEqual(len(result), 1)

    def test_iterable_input(self):
        self.assertEqual(stable_unique(iter([2, 2, 1])), [2, 1])

    def test_returns_new_list(self):
        data = [1, 2]
        result = stable_unique(data)
        self.assertIsNot(result, data)

    def test_does_not_mutate(self):
        data = [[1], 2, [1], 2, {"a": [3]}]
        before = copy.deepcopy(data)
        stable_unique(data)
        self.assertEqual(data, before)

    def test_none_values(self):
        self.assertEqual(stable_unique([None, None, 0]), [None, 0])


if __name__ == "__main__":
    unittest.main()
